export class OceanAudio {
 constructor(){this.ctx=null;this.enabled=true;this.volume=.55;this.lastGull=0;this.lastStep=0;}
 init(){if(this.ctx){this.ctx.resume();return;}const A=window.AudioContext||window.webkitAudioContext;if(!A)return;this.ctx=new A();const c=this.ctx;this.master=c.createGain();this.master.gain.value=this.volume;this.master.connect(c.destination);const buf=c.createBuffer(1,c.sampleRate*4,c.sampleRate);const d=buf.getChannelData(0);let brown=0;for(let i=0;i<d.length;i++){brown=(brown+(Math.random()*2-1)*.018)/1.019;d[i]=brown*4;}
 this.surf=c.createBufferSource();this.surf.buffer=buf;this.surf.loop=true;const f=c.createBiquadFilter();f.type='lowpass';f.frequency.value=1100;this.surfGain=c.createGain();this.surfGain.gain.value=.32;this.surf.connect(f);f.connect(this.surfGain);this.surfGain.connect(this.master);this.surf.start();
 this.engine=c.createOscillator();this.engine.type='sawtooth';this.engine.frequency.value=38;this.engineGain=c.createGain();this.engineGain.gain.value=0;const ef=c.createBiquadFilter();ef.type='lowpass';ef.frequency.value=280;this.engine.connect(ef);ef.connect(this.engineGain);this.engineGain.connect(this.master);this.engine.start();
 }
 toggle(){this.enabled=!this.enabled;if(this.ctx)this.master.gain.setTargetAtTime(this.enabled?this.volume:0,this.ctx.currentTime,.1);return this.enabled;}
 ping(freq=660,duration=.12,volume=.08,type='sine'){if(!this.ctx||!this.enabled)return;const c=this.ctx,o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+duration);o.connect(g);g.connect(this.master);o.start();o.stop(c.currentTime+duration);}
 splash(){this.ping(110,.5,.08,'triangle');this.ping(230,.2,.035,'sawtooth');}
 reel(){this.ping(1050,.025,.009,'square');}
 gull(){if(!this.ctx||!this.enabled)return;let c=this.ctx,o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.setValueAtTime(950,c.currentTime);o.frequency.linearRampToValueAtTime(1430,c.currentTime+.12);o.frequency.exponentialRampToValueAtTime(660,c.currentTime+.65);g.gain.setValueAtTime(.001,c.currentTime);g.gain.linearRampToValueAtTime(.035,c.currentTime+.12);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.7);o.connect(g);g.connect(this.master);o.start();o.stop(c.currentTime+.72);}
 update(t,engine,throttle,walking){if(!this.ctx)return;const c=this.ctx;this.surfGain.gain.setTargetAtTime(.28+Math.sin(t*.36)*.065,c.currentTime,.2);this.engine.frequency.setTargetAtTime(31+Math.abs(throttle)*56+Math.sin(t*31)*2,c.currentTime,.1);this.engineGain.gain.setTargetAtTime(engine?.025+Math.abs(throttle)*.075:0,c.currentTime,.15);if(t-this.lastGull>19){this.lastGull=t+Math.random()*18;this.gull();}if(walking&&t-this.lastStep>.42){this.lastStep=t;this.ping(85+Math.random()*35,.11,.045,'triangle');}}
}
